from collections import deque

def fewest_moves_one_break(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {grid[i][j]: (i, j) for i in range(rows) for j in range(cols) if grid[i][j] in 'SE'}

    def spread(src):
        dist = [[-1] * cols for _ in range(rows)]
        dist[src[0]][src[1]] = 0
        queue = deque([src])
        while queue:
            i, j = queue.popleft()
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and dist[a][b] < 0 and grid[a][b] != '#':
                    dist[a][b] = dist[i][j] + 1
                    queue.append((a, b))
        return dist

    ds, de = spread(cells['S']), spread(cells['E'])
    ei, ej = cells['E']
    best = ds[ei][ej]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != '#':
                continue
            near = [(a, b) for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1))
                    if 0 <= a < rows and 0 <= b < cols]
            to = [ds[a][b] for a, b in near if ds[a][b] >= 0]
            back = [de[a][b] for a, b in near if de[a][b] >= 0]
            if to and back:
                route = min(to) + min(back) + 2
                if best < 0 or route < best:
                    best = route
    return best

