from collections import deque

def fewest_moves_one_break(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {grid[i][j]: (i, j) for i in range(rows) for j in range(cols) if grid[i][j] in 'SE'}

    def steps(open_cell):
        dist = {cells['S']: 0}
        queue = deque([cells['S']])
        while queue:
            i, j = queue.popleft()
            if (i, j) == cells['E']:
                return dist[(i, j)]
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and (a, b) not in dist and (grid[a][b] != '#' or (a, b) == open_cell):
                    dist[(a, b)] = dist[(i, j)] + 1
                    queue.append((a, b))
        return -1

    best = steps(None)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#':
                d = steps((i, j))
                if d >= 0 and (best < 0 or d < best):
                    best = d
    return best
